function perfectpixel_override_price( $price, $product ) {
	// Product or variation ID => price.
	$prices          = array(
		// 123 => 19.90,
	);
	$logged_in_only = false;

	if ( ( $logged_in_only && ! is_user_logged_in() ) || is_admin() && ! wp_doing_ajax() ) {
		return $price;
	}
	$id = $product->get_id();
	return isset( $prices[ $id ] ) ? (string) $prices[ $id ] : $price;
}
